def repeated_dna(s):
    codes = {"A": 0, "C": 1, "G": 2, "T": 3}
    mask = (1 << 20) - 1
    window = 0
    seen, reported = set(), set()
    result = []
    for index, char in enumerate(s):
        window = ((window << 2) | codes[char]) & mask
        if index < 9:
            continue
        if window in seen and window not in reported:
            result.append(s[index - 9:index + 1])
            reported.add(window)
        seen.add(window)
    return result

